/* Token Radar, radar-2. Dark theme: one canvas, one surface, one accent. */
:root{
  --canvas:#0b100e; --surface:#121a17; --surface2:#182420; --ink:#e9f2ed;
  --muted:#9db4a9; --border:#24352e; --accent:#35d99a; --accent-dim:#1d7a56;
  --gold:#f2c14e; --negative:#ff8a7a; --radius:10px; --radius-panel:14px;
  --font-body:system-ui,-apple-system,"Segoe UI",sans-serif;
  --font-num:ui-monospace,"SF Mono",Menlo,Consolas,monospace;
}
*{box-sizing:border-box}
html{color-scheme:dark}
body{margin:0;background:var(--canvas);color:var(--ink);font:400 15px/1.55 var(--font-body)}
h1,h2,h3{margin:0;letter-spacing:-.02em}
h1{font-size:30px;line-height:1.15;font-weight:650}
h2{font-size:20px;line-height:1.2;font-weight:650}
h3{font-size:16px;line-height:1.25;font-weight:650}
p{margin:0}
button,input,select{font:inherit;color:inherit}
button{cursor:pointer}
.skip{position:absolute;left:-9999px;top:0;padding:8px 16px;background:var(--surface);border:1px solid var(--border);z-index:20}
.skip:focus{left:16px;top:16px}
:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.shell{max-width:1360px;margin:0 auto;padding:24px 32px 48px}
.top{display:flex;align-items:flex-start;justify-content:space-between;gap:24px;padding-bottom:16px;border-bottom:1px solid var(--border)}
.brand{display:flex;align-items:center;gap:12px}
.mark{width:12px;height:12px;border-radius:50%;background:var(--accent);flex:none}
.brand-name{font-family:var(--font-num);font-size:13px;color:var(--muted)}
.top-meta{display:flex;flex-wrap:wrap;gap:12px;justify-content:flex-end;color:var(--muted);font-size:13px}
.top-meta span{white-space:nowrap}
.lede{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(280px,.65fr);gap:32px;padding:32px 0 24px}
.lede p{color:var(--muted);max-width:62ch;margin-top:8px}
.facts{display:grid;gap:8px;align-content:start;border-left:1px solid var(--border);padding-left:24px}
.fact{display:flex;align-items:baseline;justify-content:space-between;gap:12px}
.fact b{font-family:var(--font-num);font-size:15px;font-weight:500}
.fact span{color:var(--muted);font-size:13px}
.controls{display:flex;flex-wrap:wrap;align-items:end;gap:12px;padding:16px 0;border-top:1px solid var(--border)}
.field{display:grid;gap:4px}
.field label{color:var(--muted);font-size:12px}
.field input,.field select{min-height:36px;padding:0 12px;border:1px solid var(--border);border-radius:8px;background:var(--surface);min-width:170px}
.field input{min-width:260px}
.tabs{display:flex;gap:4px;padding:3px;border:1px solid var(--border);border-radius:8px;background:var(--surface)}
.tabs button{min-height:30px;padding:0 12px;border:0;border-radius:6px;background:transparent;color:var(--muted)}
.tabs button[aria-pressed="true"]{background:var(--accent);color:#06110c;font-weight:600}
.toggle{display:inline-flex;align-items:center;gap:8px;color:var(--muted);font-size:13px;min-height:36px}
.toggle input{accent-color:var(--accent);width:16px;height:16px}
.count{margin-left:auto;color:var(--muted);font-size:13px;align-self:center}
.panel{background:var(--surface);border:1px solid var(--border);border-radius:var(--radius-panel);overflow:hidden}
.table-wrap{overflow-x:auto}
table{width:100%;border-collapse:collapse;font-size:14px}
th,td{padding:12px;border-bottom:1px solid var(--border);text-align:left;vertical-align:middle}
th{color:var(--muted);font-size:12px;font-weight:500;white-space:nowrap}
th button{display:inline-flex;align-items:center;gap:4px;border:0;background:none;padding:0;color:inherit;font:inherit}
th button:hover{color:var(--ink)}
tbody tr{cursor:pointer}
tbody tr:hover{background:var(--surface2)}
tbody tr[data-selected="true"]{background:#1b2f28}
.num{font-family:var(--font-num);font-variant-numeric:tabular-nums;white-space:nowrap}
.name{display:grid;gap:2px}
.name b{font-weight:600}
.sub{color:var(--muted);font-size:12px}
.pos{color:var(--accent)}
.neg{color:var(--negative)}
.bar{width:120px;height:6px;border-radius:3px;background:#24352e;overflow:hidden}
.bar i{display:block;height:100%;background:var(--accent)}
.implied{display:flex;align-items:center;gap:8px}
.status{display:inline-flex;align-items:center;gap:6px;color:var(--muted);font-size:12px;white-space:nowrap}
.status::before{content:"";width:6px;height:6px;border-radius:50%;background:var(--accent)}
.status.live::before{background:var(--gold)}
.badge{display:inline-block;padding:1px 7px;border:1px solid var(--border);border-radius:20px;font-size:11px;color:var(--muted)}
.badge.watch{color:var(--gold);border-color:#5a4a1e}
.model{margin-top:16px;padding:24px;display:grid;gap:12px}
.formula{font-family:var(--font-num);font-size:13px;line-height:1.7;color:var(--muted);overflow-wrap:anywhere}
.comp{width:100%;border-collapse:collapse;font-size:13px}
.comp th,.comp td{padding:6px 8px;border-bottom:1px solid var(--border)}
.empty{padding:48px 24px;text-align:center;display:grid;gap:12px;justify-items:center}
.empty p{color:var(--muted)}
.button{min-height:36px;padding:0 16px;border:1px solid var(--border);border-radius:8px;background:var(--surface)}
.button.primary{background:var(--accent);border-color:var(--accent);color:#06110c;font-weight:600}
.detail{position:fixed;top:0;right:0;bottom:0;width:min(560px,94vw);z-index:10;background:var(--surface);border-left:1px solid var(--border);padding:24px;overflow-y:auto;margin:0 0 0 auto;max-height:100%}
.detail[hidden]{display:none}
.detail::backdrop{background:rgba(0,0,0,.55)}
.detail-head{display:flex;align-items:start;justify-content:space-between;gap:16px}
.detail-head>div{min-width:0}
.close{flex:none;min-width:32px;min-height:32px;padding:0 8px;border:1px solid var(--border);border-radius:8px;background:var(--surface)}
.detail h2{margin-top:4px}
.detail .sub{margin-top:4px}
.detail-section{margin-top:20px;padding-top:16px;border-top:1px solid var(--border)}
.detail-section h3{margin-bottom:8px}
.equation{display:grid;gap:8px;font-family:var(--font-num);font-size:13px}
.equation div{display:flex;justify-content:space-between;gap:12px}
.equation span{color:var(--muted)}
.equation .total{border-top:1px solid var(--border);padding-top:8px}
.steps{margin:0;padding-left:20px;display:grid;gap:12px}
.steps li{padding-left:4px}
.steps b{display:block;font-weight:500}
.cost{color:var(--muted);font-size:12px;font-family:var(--font-num)}
.note{color:var(--muted);font-size:13px;margin-top:12px}
@media (max-width:900px){
  .shell{padding:16px}
  .lede{grid-template-columns:1fr;gap:16px}
  .facts{border-left:0;border-top:1px solid var(--border);padding-left:0;padding-top:16px}
  .field input{min-width:0;width:100%}
}
```

